import type { Preset } from "unocss";

import { presetGlitchKidsMasterFluid } from "./master-fluid-preset";
import { presetGlitchKidsMasterGrid } from "./master-grid-presets";

export function UnoGlitchKidsPreset(): Preset {
  return {
    name: "uno-glitchkids-preset",
    presets: [presetGlitchKidsMasterFluid({}), presetGlitchKidsMasterGrid({})],
    preflights: [
      {
        getCSS: () => `
            * {
                font-family: Poppins, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
            }

            body {
                @apply bg-black text-primary-white;
            }

            .no-scrollbar::-webkit-scrollbar {
                display: none;
            }

            .no-scrollbar {
                -ms-overflow-style: none;  
                scrollbar-width: none;  
            }
            `,
      },
    ],
  };
}

import type { Preset } from "unocss";

// PresetGlitchKidsMasterFluid v1.0.0-beta.1

export function presetGlitchKidsMasterFluid({
  minWidth = 320,
  maxWidth = 1920,
  minHeight = 275,
  maxHeight = 720,
}) {
  const properties = {
    rounded: ["border-radius"],
    w: ["width"],
    h: ["height"],
    size: ["width", "height"],
    "min-w": ["min-width"],
    "min-h": ["min-height"],
    "max-w": ["max-width"],
    "max-h": ["max-height"],
    p: ["padding"],
    pt: ["padding-top"],
    pr: ["padding-right"],
    pb: ["padding-bottom"],
    pl: ["padding-left"],
    px: ["padding-left", "padding-right"],
    py: ["padding-top", "padding-bottom"],
    m: ["margin"],
    mt: ["margin-top"],
    mr: ["margin-right"],
    mb: ["margin-bottom"],
    ml: ["margin-left"],
    mx: ["margin-left", "margin-right"],
    my: ["margin-top", "margin-bottom"],
    gap: ["gap"],
    "column-gap": ["column-gap"],
    "row-gap": ["row-gap"],
    top: ["top"],
    right: ["right"],
    bottom: ["bottom"],
    left: ["left"],
    text: ["font-size"],
    leading: ["line-height"],
  };
  function toNormalizedValuePixels(value: number) {
    return value * 4;
  }

  function fluidClamp(
    minValue: number,
    maxValue: number,
    min: number,
    max: number,
  ) {
    const slope = toNormalizedValuePixels(maxValue - minValue) / (max - min);
    const slopeValue = slope * 100;
    const intercept = toNormalizedValuePixels(minValue) - slope * min;
    return `clamp(calc(${minValue} * 0.25rem), calc(${slopeValue}vw + ${intercept}px), calc(${maxValue} * 0.25rem))`;
  }
  function returnResult(property: keyof typeof properties, value: string) {
    if (!(property in properties)) return {};
    return properties[property].map((property) => [property, value]);
  }

  return {
    name: "unocss-preset-glitchkids-fluid",
    autocomplete: {
      templates: ["f-<property>-<num>/<num>"],
      shorthands: {
        property: Object.keys(properties),
      },
    },
    rules: [
      [
        /^f-(.+)-(\d+(\.\d+)?)\/(\d+(\.\d+)?)$/,
        ([_, property, minValue, __, maxValue]) => {
          const value = fluidClamp(
            Number(minValue),
            Number(maxValue),
            minWidth,
            maxWidth,
          );
          return returnResult(property as keyof typeof properties, value);
        },
      ],
      [
        /^fv-(.+)-(\d+)\/(\d+)$/,
        ([_, property, minValue, maxValue]) => {
          const value = fluidClamp(
            Number(minValue),
            Number(maxValue),
            minHeight,
            maxHeight,
          );
          return returnResult(property as keyof typeof properties, value);
        },
      ],
    ],
  } satisfies Preset;
}

import type { Preset } from "unocss";

// PresetGlitchKidsMasterGrid v1.0.0-beta.1

export function presetGlitchKidsMasterGrid({
  paddingX = 1.5,
  maxContainerWidth = 80,
}) {
  return {
    name: "unocss-preset-glitchkids-master-grid",
    rules: [
      [
        /master-grid-(\d+)/,
        ([_, colNumber]) => {
          return {
            display: "grid",
            "grid-template-columns": `
              minmax(${paddingX}rem, 1fr) 
              repeat(${colNumber}, minmax(0, calc(${maxContainerWidth}rem / ${colNumber}))) 
              minmax(${paddingX}rem, 1fr)`,
          };
        },
      ],
      [
        "master-grid-container",
        {
          display: "grid",
          "grid-template-columns": "subgrid",
          "grid-column": "1 / -1",
        },
      ],
      [
        "master-grid-subgrid-container",
        {
          display: "grid",
          "grid-template-columns": "subgrid",
          "grid-column": "1 / -1",
        },
      ],
      [
        "master-grid-subgrid",
        {
          display: "grid",
          "grid-template-columns": "subgrid",
          "grid-column": "2 / -2",
          "column-gap": "24px",
        },
      ],
      [
        /master-grid-col-center-(\d+)/,
        ([_, colNumber]) => {
          return {
            "grid-column": `${colNumber} / -${colNumber}`,
          };
        },
      ],
      [
        "master-grid-container-full",
        {
          "grid-column": "2 / -2",
        },
      ],
    ],
  } satisfies Preset;
}

